def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Initialize the grid with zeros
    grid = [[0] * N for _ in range(N)]

    # Fill the grid with the given values
    for x, y, value in grid_values:
        grid[x][y] = value

    # Initialize the maximum values for the first and second paths
    max_path1 = 0
    max_path2 = 0

    # Fill the first path from top-left to bottom-right
    for i in range(N):
        for j in range(N):
            if i == 0 and j == 0:
                grid[i][j] = grid[i][j]
            elif i == 0:
                grid[i][j] = grid[i][j-1] + grid[i][j]
            elif j == 0:
                grid[i][j] = grid[i-1][j] + grid[i][j]
            else:
                grid[i][j] = max(grid[i-1][j], grid[i][j-1]) + grid[i][j]
            max_path1 = max(max_path1, grid[i][j])

    # Fill the second path from bottom-right to top-left
    for i in range(N-1, -1, -1):
        for j in range(N-1, -1, -1):
            if i == N-1 and j == N-1:
                grid[i][j] = grid[i][j]
            elif i == N-1:
                grid[i][j] = grid[i][j+1] + grid[i][j]
            elif j == N-1:
                grid[i][j] = grid[i+1][j] + grid[i][j]
            else:
                grid[i][j] = max(grid[i+1][j], grid[i][j+1]) + grid[i][j]
            max_path2 = max(max_path2, grid[i][j])

    # The maximum sum of values collected on the two paths
    return max(max_path1, max_path2)

def find_number_combinations():
    """
    Generate all unique combinations of three numbers, each formed from the digits 1 to 9 without repetition,
    such that the second number is twice the first and the third is three times the first.

    Returns:
        list of tuples: A sorted list of tuples, where each tuple contains three integers representing the
                        valid number combinations in ascending order based on the first number.

    Example:
        >>> find_number_combinations()
        [(123, 246, 369), (124, 248, 372), ...]
    """
    combinations = []
    for i in range(1, 10):
        for j in range(i * 2, 10):
            for k in range(j * 3, 10):
                if i != j and j != k and i != k:
                    combinations.append((i, j, k))
    return sorted(combinations)

def cantor_numbering(N: int) -> str:
    """
    Determines the numerator and denominator of the N-th term in the Cantor table.

    Args:
    - N (int): The position in the Cantor table to find the corresponding fraction for.

    Returns:
    - str: A string representation of the fraction at the N-th position in the Cantor table.
    """
    if N == 0:
        return "1/1"
    elif N % 2 == 0:
        return cantor_numbering(N // 2) + "/" + cantor_numbering(N // 2 + 1)
    else:
        return cantor_numbering(N // 2) + "/" + cantor_numbering(N // 2 + 1) + "/" + cantor_numbering(N // 2 + 2)

