def preorder_traversal(inorder: str, postorder: str) -> str:
    if not inorder or not postorder:
        return ""

    root_val = postorder[-1]
    root_index = inorder.index(root_val)

    left_inorder = inorder[:root_index]
    right_inorder = inorder[root_index + 1:]
    left_postorder = postorder[:root_index]
    right_postorder = postorder[root_index:-1]

    return preorder_traversal(left_inorder, left_postorder) + root_val + preorder_traversal(right_inorder, right_postorder)

from collections import deque

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    if A == B:
        return 0

    queue = deque([(A, 0)])
    visited = set([A])

    while queue:
        current, steps = queue.popleft()

        if current == B:
            return steps

        for src, tgt in rules:
            if src in current:
                new_str = current.replace(src, tgt)
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, steps + 1))

    return "NO ANSWER!"

def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

