def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            for k in range(1, a[i - 1] + 1):
                dp[i][j] = (dp[i][j] + dp[i - 1][j - k]) % MOD

    return dp[n][m]

def jinjin_savings_plan(budgets: List[int]) -> int:
    total_savings = 0
    for month, budget in enumerate(budgets):
        if budget >= 100:
            savings = min(budget, 300)
            total_savings += savings
            budget -= savings
            if budget < 100:
                return -month
        else:
            return -month
    return total_savings * 1.20

def minimum_students_to_leave(heights):
    n = len(heights)
    left = 0
    right = n - 1
    count = 0

    while left < right:
        if heights[left] < heights[right]:
            left += 1
        else:
            count += 1
            right -= 1

    return count

def hanoi_double_iterative(n: int) -> int:
    # Base cases
    if n == 1:
        return 2
    elif n == 2:
        return 6
    elif n == 3:
        return 14

    # Recursive relation for n pairs of discs
    return 2 * hanoi_double_iterative(n - 1) + 4

def total_smoked_cigarettes(n, k):
